int main() {
  int n;
  int *v;

  scanf("%d", &n);
  if (reservarEnteros(&v, n) == FALSO) {
    printf("Sin memoria");
    return 0;
  }
  for (int i = 0; i < n; i++) {
    v[i] = i * 2;
    printf("%d ", v[i]);
  }
  free(v);
  return 0;
}

consignas.referencia:
typedef enum {
  FALSO,
  VERDADERO
} TBool;

TBool reservarEnteros(int **v, int n) {
  *v = malloc(n * sizeof(int));
  if (*v == NULL) {
    return FALSO;
  }
  return VERDADERO;
}

